(function(root){
'use strict';const H=typeof module!=='undefined'?require('./officer-model.js'):root.Hive,data=typeof module!=='undefined'?require('./template-data.js'):root.HiveTemplateData,copy=x=>JSON.parse(JSON.stringify(x));
function catalogue(){const lun=H.lunReference();return[{...lun,id:'lun',name:'LUN',description:'Your saved two-trap layout.',origin:'Saved WOS Nerds layout'},...copy(data)]}
function geometry(id){const p=catalogue().find(p=>p.id===id);if(!p)throw Error('Template not found.');return p}
function apply(s,id,{x=s.settings.anchorX,y=s.settings.anchorY}={}){if(![x,y].every(v=>Number.isInteger(v)&&v>=0&&v<=1197))throw Error('Enter valid whole coordinates for BT1.');const n=copy(s),p=geometry(id),first=p.traps.find(t=>t.id===1),o=H.worldOrigin(n),dx=x-o.x-first.x,dy=y-o.y-first.y;for(const key of ['traps','slots','blocks','structures'])n[key]=copy(p[key]||[]).map(b=>({...b,x:b.x+dx,y:b.y+dy}));if([...n.traps,...n.slots,...n.blocks,...n.structures].some(b=>b.x+o.x<0||b.y+o.y<0||b.x+o.x+b.w>1200||b.y+o.y+b.h>1200))throw Error('This template extends beyond the world map. Move BT1 farther from the edge.');n.settings.anchorX=x;n.settings.anchorY=y;const t2=n.traps.find(t=>t.id===2);if(t2){n.settings.anchor2X=o.x+t2.x;n.settings.anchor2Y=o.y+t2.y}n.slots=n.slots.map(b=>{const t=n.traps.find(t=>t.id===b.trap)||[...n.traps].sort((a,c)=>Math.hypot(b.x-a.x,b.y-a.y)-Math.hypot(b.x-c.x,b.y-c.y))[0];return{...b,trap:t.id,row:H.cityRow(b,t)}});n.members.forEach(m=>Object.assign(m,{slot:null,locked:false,confirmed:false,verified:false}));n.settings.verified=false;n.layoutSource={name:p.name,url:p.source||'',origin:p.origin};const blocked=n.slots.filter(b=>H.worldBlocked(n,b)),fixedConflicts=[...n.traps,...n.structures].filter(b=>H.worldBlocked(n,b,b.kind||'trap'));return{state:n,blocked:blocked.length,fixedConflicts:fixedConflicts.length}}
H.templateCatalogue=catalogue;H.templateGeometry=geometry;H.applyHiveTemplate=apply;
if(typeof module!=='undefined')module.exports=H;
})(typeof window!=='undefined'?window:globalThis);
